import { Link } from 'react-router-dom'
import { Temu } from './Temu'
import { growth, LINEAGES, STAGES } from './model'
import { useI18n } from '@/i18n'
import { humanDuration } from './duration'
import { Card } from '@/components/ui'
import { Icon } from '@/design-system/Icon'
import './companion.css'

/**
 * The whole decade, side by side.
 *
 * This exists for the same reason the icon gallery does: inconsistency is
 * obvious when you see the set together and invisible one screen at a time.
 * Reachable at `#/temu/perjalanan`, and captured by the screenshot suite.
 */
export default function Journey() {
  const { t } = useI18n()

  return (
    <div className="stack">
      <h1>{t('temu.gallery')}</h1>
      <p className="card__hint">{t('temu.galleryHint')}</p>

      {/* The one action on an otherwise read-only screen. Without it the page
          was a dead end wearing a title — the empty-shell sweep flagged it. */}
      <Link to="/temu" className="btn btn--soft btn--sm" style={{ alignSelf: 'flex-start' }}>
        <Icon name="chevron-left" size={16} />
        {t('temu.backToTemu')}
      </Link>

      {/* The rules, before the pictures. Someone landing here wants to know
          WHEN it changes, not just what the shapes look like. */}
      <Card title={t('temu.howTitle')} icon="info">
        <p className="card__hint">{t('temu.howBody')}</p>
        <p className="card__hint" style={{ marginTop: 'var(--space-2)' }}>
          <strong>{t('temu.howTwo')}.</strong> {t('temu.howTwoBody')}
        </p>
      </Card>

      <Card title={t('temu.gallery')} icon="cycle">
        <div className="temu-journey">
          {STAGES.map((s) => {
            const g = growth(s.pairDays, s.relationshipDays)
            return (
              <div key={s.id} className="temu-journey__cell">
                <Temu growth={g} lineage="awal" mood="calm" size={104} />
                <strong>{t('temu.formNumber', { n: s.evolution ?? 1, total: STAGES.length })}</strong>
                <b>{t(s.name)}</b>
                <span>
                  {s.pairDays === 0
                    ? t('temu.needStart')
                    : t('temu.needBoth', {
                        pair: t(humanDuration(s.pairDays).key, humanDuration(s.pairDays).vars),
                        rel: t(humanDuration(s.relationshipDays).key, humanDuration(s.relationshipDays).vars),
                      })}
                </span>
              </div>
            )
          })}
        </div>
      </Card>

      <Card title={t('temu.lineage')} icon="heart" hint={t('temu.lineagePick')}>
        <div className="temu-journey">
          {LINEAGES.map((l) => (
            <div key={l} className="temu-journey__cell">
              <Temu growth={growth(365, 365)} lineage={l} mood="happy" size={104} />
              <strong>{t(`temu.lineage.${l}` as const)}</strong>
            </div>
          ))}
        </div>
      </Card>

      <Card title={t('temu.expressions')} icon="checkin">
        <div className="temu-journey">
          {(['calm', 'happy', 'celebrate', 'waiting', 'sleepy', 'curious', 'shy', 'proud', 'concerned'] as const).map(
            (m) => (
              <div key={m} className="temu-journey__cell">
                <Temu growth={growth(365, 365)} lineage="rimbun" mood={m} size={104} />
                <strong>{t(`temu.mood.${m}` as const)}</strong>
              </div>
            ),
          )}
        </div>
      </Card>
    </div>
  )
}
