import type { MessageKey, Vars } from '@/i18n'

/**
 * Turns a day count into the largest unit that still reads honestly.
 *
 * The journey screen used to print the raw gates as "3 · 2", which is
 * meaningless to anyone who has not read the source. "3 hari" and "2 tahun"
 * are the same data, said in a way a person can act on.
 *
 * Rounding stays coarse on purpose: "1.9 tahun" invites someone to work out
 * exactly which day Temu changes, and the whole point is that this is not a
 * countdown you optimise.
 */
export function humanDuration(days: number): { key: MessageKey; vars: Vars } {
  if (days >= 365) return { key: 'temu.dur.year', vars: { n: Math.round((days / 365) * 10) / 10 } }
  if (days >= 60) return { key: 'temu.dur.month', vars: { n: Math.round(days / 30) } }
  if (days >= 14) return { key: 'temu.dur.week', vars: { n: Math.round(days / 7) } }
  return { key: 'temu.dur.day', vars: { n: days } }
}
